const editor=document.querySelector('[data-editor]');
const output=document.querySelector('[data-output]');
const status=document.querySelector('[data-load-status]');
const runButton=document.querySelector('[data-run-code]');
const initialCode=editor?.value||'';
const examples={
  snack:'snack = "mochi"\njumlah = 3\nprint(f"Aku punya {jumlah} {snack} 🍡")\nprint(f"Kalau dibagi dua: {jumlah / 2}")',
  playlist:'playlist_kucing = ["Meongpop", "Purrfect", "Miau Mellow"]\nfor nomor, lagu in enumerate(playlist_kucing, start=1):\n    print(f"{nomor}. {lagu} 🎧")',
  guess:'import random\nrahasia = random.randint(1, 5)\ntebakan = 3\nprint(f"Angka rahasianya {rahasia}.")\nif tebakan == rahasia:\n    print("Tebakan tepat! Pipi joget 💃")\nelse:\n    print(f"Tebakan {tebakan}, belum cocok. Coba lagi!")'
};
let pyodidePromise=null;
function setStatus(message){if(status)status.textContent=message}
function friendlyError(error){const raw=String(error?.message||error);if(raw.includes('SyntaxError'))return `Sepertinya ada typo sintaks. Periksa tanda kurung, kutip, dan titik dua (:).\n\nDetail: ${raw.split('\n')[0]}`;if(raw.includes('NameError'))return `Ada nama variabel atau fungsi yang belum dikenal Python. Cek ejaan dan pastikan sudah dibuat.\n\nDetail: ${raw.split('\n')[0]}`;if(raw.includes('IndentationError')||raw.includes('TabError'))return `Indentasi Python belum rata. Gunakan 4 spasi untuk setiap blok kode.\n\nDetail: ${raw.split('\n')[0]}`;if(raw.includes('ModuleNotFoundError')||raw.includes('ImportError'))return `Modul itu belum tersedia di playground. Modul standar Python bisa dipakai; paket lain perlu dipasang lebih dulu.\n\nDetail: ${raw.split('\n')[0]}`;return `Pipi menemukan kendala saat menjalankan kode. Cek baris yang disebut dan coba lagi.\n\nDetail: ${raw.split('\n')[0]}`}
function loadScript(){if(window.loadPyodide)return Promise.resolve();if(pyodidePromise)return pyodidePromise;pyodidePromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/pyodide/v0.29.3/full/pyodide.js';script.onload=resolve;script.onerror=()=>reject(new Error('CDN Pyodide tidak bisa dimuat. Periksa koneksi internet lalu coba lagi.'));document.head.append(script)});return pyodidePromise}
async function getRuntime(){if(window.pypinkPyodide)return window.pypinkPyodide;setStatus('Pipi sedang menyiapkan ruang ngoding… unduhan pertama agak besar 🐍');runButton.disabled=true;runButton.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Menyiapkan Python…';await loadScript();window.pypinkPyodide=await window.loadPyodide({indexURL:'https://cdn.jsdelivr.net/pyodide/v0.29.3/full/'});return window.pypinkPyodide}
runButton?.addEventListener('click',async()=>{if(!editor||!output)return;runButton.disabled=true;output.textContent='';try{const pyodide=await getRuntime();const lines=[];pyodide.setStdout({batched:line=>lines.push(line)});pyodide.setStderr({batched:line=>lines.push(line)});setStatus('Pipi membaca kode kamu…');await pyodide.runPythonAsync(editor.value);output.textContent=lines.join('\n')||'Program berjalan tanpa output.';setStatus('Selesai! Pipi ikut tepuk tangan ✨');window.pypinkToast?.('Kode Python berhasil dijalankan! ✨')}catch(error){output.textContent=friendlyError(error);setStatus('Ada sedikit yang perlu dibetulkan. Kamu pasti bisa!');window.pypinkToast?.('Ada typo kecil? Pipi bantu cari 🐍')}finally{runButton.disabled=false;runButton.innerHTML='<i class="fa-solid fa-play"></i> Jalankan'}});
document.querySelector('[data-reset-code]')?.addEventListener('click',()=>{if(editor)editor.value=initialCode;if(output)output.textContent='Hasil program akan muncul di sini…';setStatus('Kode direset. Pipi siap menunggu kode baru!')});
document.querySelector('[data-example-select]')?.addEventListener('change',event=>{if(editor)editor.value=examples[event.target.value]||initialCode;if(output)output.textContent='Hasil program akan muncul di sini…';setStatus('Contoh dimuat. Silakan Jalankan!')});
try{const shared=sessionStorage.getItem('pypink-playground-code');if(shared){editor.value=shared;sessionStorage.removeItem('pypink-playground-code');setStatus('Kode materi sudah dimuat. Tinggal tekan Jalankan!')}}catch{}
